// #45f435 (6a993d743e771e2d8145f435), треб.8 — «Super Admin רשאי לבצע את אותן פעולות קישור לצורכי תמיכה, בתיעוד מלא».
// admin: /admin/businesses → testim → «קישורי מועמדים» (причина обязательна: «תמיכה תפעולית») → «הארכה», «קישור חדש»,
// «ביטול» на СВОЁМ кандидате; после каждого действия прежняя ссылка у гостя — S-11; в «רישום גישה» три действия
// от «מנהל מערכת» с «תמיכה תפעולית». Кейс LINK-006. Три роли (business, admin, гость) — записано autotest-writer вручную.
// НЕ prod-safe: создаёт кандидата «QA-AUTO-45f435-SA-…» (link_only), ничего не удаляет; чужие строки не трогает.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { createCandidateLink } from '../candidate-call/support';
import { candidateId, currentLink, expectInactive } from './support';

const HASH = '#45f435';
const BUSINESS = process.env.QA_TESTIM_BUSINESS || 'testim';
const REASON = 'תמיכה תפעולית';

/** admin: карточка бизнеса → «קישורי מועמדים» с причиной → строка кандидата. */
async function linksRow(admin: Page, name: string) {
  await admin.goto('/admin/businesses');
  await admin.locator('a, button, tr, [role=row]').filter({ hasText: BUSINESS }).first().click();
  await expect(admin.getByText('קישורי מועמדים', { exact: true })).toBeVisible({ timeout: 30_000 });
  const show = admin.getByRole('button', { name: 'הצגת הקישורים' });
  await expect(admin.getByTestId('candidate-link-row')).toHaveCount(0); // без причины список не показан
  await admin.locator('select').filter({ hasText: REASON }).first().selectOption({ label: REASON });
  const list = admin.waitForResponse((r) => r.url().includes('/rpc/admin_list_business_candidate_links'));
  await show.click();
  expect((await list).status()).toBe(200);
  const row = admin.getByTestId('candidate-link-row').filter({ hasText: name });
  await expect(row, `нет строки «${name}» в «קישורי מועמדים»`).toHaveCount(1);
  return row;
}

/** admin: действие в строке → окно подтверждения → кнопка; POST rpc 200. */
async function rowAction(admin: Page, name: string, testId: string, confirm: string, rpc: RegExp) {
  const row = await linksRow(admin, name);
  await row.getByTestId(testId).click();
  const dialog = admin.locator('[role=dialog], [role=alertdialog]').filter({ has: admin.getByRole('button', { name: 'חזרה', exact: true }) }).last();
  await expect(dialog).toBeVisible();
  await expect(dialog).toContainText(name);
  const res = admin.waitForResponse((r) => rpc.test(r.url()) && r.request().method() === 'POST');
  await dialog.getByRole('button', { name: confirm, exact: true }).click();
  expect((await res).status(), `${confirm}: ответ ${rpc}`).toBe(200);
  await expect(dialog).toBeHidden();
  return row;
}

test.describe(`Super Admin — действия со ссылкой кандидата для поддержки (${HASH})`, () => {
  test(`admin «קישורי מועמדים» (причина «תמיכה תפעולית»): продление, новая ссылка, отмена — прежняя ссылка гаснет каждый раз; в «רישום גישה» три записи «מנהל מערכת» / «תמיכה תפעולית» @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(5 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-45f435-SA-${runStamp()}`;
    const link0 = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}»: ссылки продлены/перевыпущены/отменены Super Admin, не удаляется` });
    const id = await candidateId(business, name);

    const admin = await asUser('admin');
    const guest = await asUser('guest');

    // 1. Продление — новая ссылка, прежняя не работает.
    let row = await rowAction(admin, name, 'extend-candidate-link', 'הארכת התוקף', /\/rpc\/[a-z_]*extend[a-z_]*/);
    expect(await row.getAttribute('data-candidate-id'), 'строка SA = кандидат business').toBe(id);
    await expectInactive(guest, link0);
    const link1 = await currentLink(business, id);
    expect(new URL(link1).pathname).not.toBe(new URL(link0).pathname);

    // 2. Новая ссылка.
    await rowAction(admin, name, 'reissue-candidate-link', 'הפקת קישור חדש', /\/rpc\/[a-z_]*(reissue|regenerate)[a-z_]*/);
    await expectInactive(guest, link1);
    const link2 = await currentLink(business, id);
    expect(new URL(link2).pathname).not.toBe(new URL(link1).pathname);

    // 3. Отмена — статус «בוטל».
    row = await rowAction(admin, name, 'cancel-candidate-link', 'ביטול הקישור', /\/rpc\/[a-z_]*cancel[a-z_]*/);
    await expect(row).toContainText('בוטל');
    await expectInactive(guest, link2);

    // 4. Журнал: фильтр по кандидату. Источник: треб.8 — «בתיעוד מלא».
    await admin.goto('/admin/access-log');
    await expect(admin.getByRole('heading', { level: 1, name: 'רישום גישה' })).toBeVisible();
    await admin.getByLabel('מזהה מועמד').fill(id);
    const filtered = admin.waitForResponse((r) => r.url().includes('/rpc/admin_list_access_log'));
    await admin.getByRole('button', { name: 'סינון', exact: true }).click();
    expect((await filtered).status()).toBe(200);
    const table = admin.getByRole('table');
    for (const action of ['הארכת תוקף קישור מועמד', 'הפקת קישור מועמד חדש', 'ביטול קישור מועמד']) {
      const entry = table.getByRole('row').filter({ hasText: action });
      await expect(entry, `в журнале нет «${action}»`).toHaveCount(1);
      await expect(entry).toContainText('מנהל מערכת');
      await expect(entry).toContainText(BUSINESS);
      await expect(entry).toContainText(REASON);
    }
  });
});
